// Photos réelles du Groupe Scolaire Sayl (source : page Facebook officielle). Contenu base64 : ne pas modifier.
export const PHOTOS: Record<string, string> = {
  "01_transport_bus": "data:image/jpeg;base64,",
  "02_eleves_sortie": "data:image/jpeg;base64,",
  "03_piscine": "data:image/jpeg;base64,",
  "04_sortie_nature": "data:image/jpeg;base64,",
  "05_sport_football": "data:image/jpeg;base64,",
  "06_concours_coran": "data:image/jpeg;base64,",
  "07_fete_tenues_traditionnelles": "data:image/jpeg;base64,",
  "08_securite_routiere": "data:image/jpeg;base64,",
  "09_maquette_securite_routiere": "data:image/jpeg;base64,",
  "10_transport_sortie": "data:image/jpeg;base64,",
  "11_fete_des_meres": "data:image/jpeg;base64,",
  "12_sortie_zoo": "data:image/jpeg;base64,",
};
export const photo = (name: string): string => PHOTOS[name.replace(/^.*\//, "").replace(/\.jpe?g$/i, "")] ?? "";
